def maximum_units(box_types, truck_size):
    box_types.sort(key=lambda x: -x[1])                 # sort by units per box, descending
    total = 0
    for count, units in box_types:
        take = min(count, truck_size)
        total += take * units
        truck_size -= take
        if truck_size <= 0:
            break
    return total

