import java.util.*;

public class Main {
    static int maximumUnits(int[][] boxTypes, int truckSize) {
        Arrays.sort(boxTypes, (a, b) -> b[1] - a[1]);            // sort by units per box, descending
        int total = 0;
        for (int[] bt : boxTypes) {
            int take = Math.min(bt[0], truckSize);
            total += take * bt[1];
            truckSize -= take;
            if (truckSize <= 0) break;
        }
        return total;
    }
}

